/** Machine translated draft; religious and linguistic review pending. */
internal object DuaKoDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("알라후마 비카 아스바나", "오 알라, 당신으로 인해 우리는 아침에 들어가고 당신으로 인해 저녁에 들어갑니다. 우리는 당신으로 살고 당신으로 죽습니다. 그리고 당신에게 부활도 있습니다.", "아침에.", "선지자 ﷺ은 동료들에게 오늘 아침과 저녁에 말하도록 가르쳤습니다."),
        "dua_allahumma_bika_amsayna" to DuaText("알라후마 비카 암사이나", "오 알라, 당신으로 인해 우리는 저녁에 들어가고 당신으로 인해 아침에 들어갑니다. 우리는 당신으로 인해 살고 당신으로 죽으며, 당신께로 돌아갑니다.", "저녁에.", "선지자 ﷺ은 동료들에게 오늘 아침과 저녁에 말하도록 가르쳤습니다."),
        "dua_afiyah_morning" to DuaText("아피야(Afiyah)를 요청하다", "오 알라여, 현세와 내세에서 용서와 안녕을 구합니다.", "예언자 ﷺ은 아침이든 저녁이든 이 두아를 떠나지 않았습니다.", "웰빙보다 더 나은 것은 누구에게도 주어지지 않았습니다."),
        "dua_afini_fi_badani" to DuaText("신체, 청각 및 시력의 건강", "오 알라시여, 내 몸에 안녕을 주소서. 오 알라, 내 청력에 안녕을 주소서. 오 알라, 내 눈에 행복을 주소서. 당신 외에는 신이 없습니다.", "매일 아침, 저녁 세 번씩.", "건강과 감각 보호를 위한 이중 제품입니다."),
        "dua_ya_hayyu_aslih" to DuaText("내 모든 일을 바로잡아라", "오 영원하신 분이시여, 오 유지하시는 분이시여, 나는 당신의 자비로 도움을 구합니다. 내 모든 일을 바로잡고 눈 깜박할 사이에도 나를 내버려 두지 마십시오.", "예언자 ﷺ은 파티마 (RA)에게 아침저녁으로 이 말을 하라고 조언했습니다.", "모든 문제에 있어서 알라의 도움을 구합니다."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Juwayriyah의 Tasbeeh (RA)", "알라께 영광을 돌리고 모든 찬양은 그분의 것입니다. 그분이 창조하신 만큼, 그분이 기뻐하시는 만큼, 그분의 보좌의 무게와 그분의 말씀의 잉크와 같습니다.", "아침에 세 번 – 몇 시간의 dhikr보다 더 무겁습니다.", "이 네 가지 문구를 세 번 말하는 것은 새벽부터 오전 중반까지 dhikr보다 더 큽니다."),
        "dua_salawat" to DuaText("두루드에 이브라히미", "오 알라, 당신이 이브라힘 (AS)과 이브라힘의 가족에게 기도를 보내신 것처럼 무함마드 ﷺ과 무함마드의 가족에게도 기도를 보내 주십시오. 당신은 칭찬받을 만하고 영광스럽습니다. 오 알라, 당신이 이브라힘 (AS)와 이브라힘의 가족을 축복하신 것처럼 무함마드 ﷺ과 무함마드의 가족을 축복하십시오. 당신은 칭찬받을 만하고 영광스럽습니다.", "항상 기도하며 선지자 ﷺ에 대한 Salawat.", "한 번 살라와트를 보내는 사람에게는 알라께서 그에게 열 가지 자비를 베푸십니다(무슬림 408)."),
        "dua_wudu_after" to DuaText("우두 이후", "나는 어떠한 동반자도 없는 유일한 알라 외에는 경배받을 분이 없으며 무함마드 ﷺ은 그분의 종이자 사도임을 간증합니다. 오 알라여, 나를 회개하는 자들과 스스로를 정화하는 자들 가운데 있게 하소서.", "우두를 마친 후.", "천국의 여덟 문은 그가 원하는 대로 들어갈 수 있도록 열려 있습니다."),
        "dua_wudu_before" to DuaText("우두 전", "알라의 이름으로.", "우두를 시작할 때.", "알라의 이름을 언급하지 않는 사람에게는 (완전한) 우두가 없습니다."),
        "dua_istiftah" to DuaText("개통요원(사나)", "오 알라, 당신께 영광을 돌리고 당신께 찬미를 드립니다. 주의 이름이 찬송을 받으시며 폐하께서 높임을 받으시니 주 외에는 신이 없나이다", "기도가 시작될 때, 탁비르가 열린 직후.", "Sunnah는 기도의 두아를 시작합니다."),
        "dua_ruku" to DuaText("루쿠에 위치", "위대하신 나의 주님께 영광을 돌립니다.", "루쿠에서는 적어도 세 번.", "루쿠의 Sunnah tasbih."),
        "dua_sujood" to DuaText("수주드에 위치", "지극히 높으신 나의 주님께 영광을 돌립니다.", "수주드에서는 적어도 세 번.", "종은 부복하는 동안 주님과 가장 가까워집니다(무슬림 482)."),
        "dua_rising_ruku" to DuaText("루쿠에서 일어나다", "알라는 자신을 찬양하는 사람의 말을 듣습니다. 우리 주여, 모든 찬양은 당신께 있습니다.", "루크에서 일어나 똑바로 서면서.", "누구든지 'Rabbana wa lakal-hamd'가 천사들의 것과 일치하면 그의 과거 죄가 용서됩니다."),
        "dua_between_sajdas" to DuaText("두 Sajdas 사이", "주님, 저를 용서해 주십시오. 주님, 저를 용서해 주십시오.", "두 절 사이에 앉아있는 동안.", "부복 사이에 앉는 Sunnah dua."),
        "dua_before_salam_four" to DuaText("네 가지 것으로부터 피난처(살람 전)", "오 알라, 나는 지옥의 형벌, 무덤의 형벌, 삶과 죽음의 시련, 그리고 거짓 메시아(다잘)의 악한 시련으로부터 당신께 피난처를 구합니다.", "마지막 tashahhud와 salawat 이후, salam 전.", "선지자 ﷺ은 이 네 가지로부터 피난처를 구하라고 명령했습니다."),
        "dua_qunoot_witr" to DuaText("Witr의 쿠누트", "오 알라시여, 당신이 인도하신 이들 가운데 나를 인도하시고, 당신께서 행복을 허락하신 이들 가운데서 나에게 행복을 주소서. 당신께서 돌보시던 이들 가운데서 나를 당신의 보살핌으로 받아들이시고, 당신께서 주신 것에 축복을 주시고, 당신이 명령하신 악으로부터 나를 보호해 주소서. 당신께서는 당신을 대적하는 명령을 내리셨으나 아무도 당신을 대적하지 않으시며, 당신이 친구가 되는 사람은 결코 굴욕을 당하지 않습니다. 우리 주님, 당신은 송축되고 높임을 받으십니다.", "위트르 기도에서 선지자 ﷺ은 하산 이븐 알리 (RA)에게 그것을 가르쳤습니다.", "witr의 Sunnah qunoot. (하나피 중에는 'Allahumma inna nasta'inuka'도 잘 알려져 있습니다.)"),
        "dua_qunoot_hanafi" to DuaText("쿠누트(Allahumma Inna Nasta'inuka)", "오 알라, 우리는 당신의 도움과 용서를 구합니다. 우리는 당신을 믿고 의지하며 최선의 방법으로 당신을 찬양하고 감사하며 배은망덕하지 않으며 당신에게 불순종하는 사람을 버립니다. 오 알라, 우리는 당신만을 예배합니다. 우리는 당신에게 기도하고 엎드리며, 당신을 향해 서두르고 노력하며, 당신의 자비를 바라고 당신의 형벌을 두려워합니다. 반드시 당신의 형벌이 불신자들에게 미칠 것입니다.", "In witr — Hanafis의 관행.", "Qunoot의 Umar (RA)에서 보고되었습니다."),
        "dua_sleep_aslamtu" to DuaText("잠들기 전 마지막 말", "오 알라, 나는 당신에 대한 희망과 당신에 대한 두려움으로 나 자신을 당신에게 복종하고, 내 일을 당신에게 맡기고, 당신의 보호에 내 등을 맡깁니다. 당신 외에는 피난처도 없고 탈출구도 없습니다. 나는 당신께서 계시하신 책과 당신이 보내신 선지자를 믿습니다.", "우두(wudu) 후, 오른쪽으로 누워 잠자기 전 마지막 말.", "그날 밤 죽으면 피트라(이슬람)에서 죽는다."),
        "dua_waking_night" to DuaText("밤에 일어나기", "어떠한 동반자도 없는 유일한 알라 외에는 경배받을 분이 없습니다. 그분의 통치권과 찬양도 그분에게 있으며, 그분은 만물을 다스리는 능력을 갖고 계십니다. 모든 찬양은 알라를 위한 것이며, 영광은 알라에게 있습니다. 알라 외에는 누구도 경배받을 권리가 없으며, 알라는 가장 위대하시며, 알라 외에는 힘도 능력도 없습니다. 오 알라, 용서해주세요.", "밤에 깨어날 때.", "그의 두아(dua)가 응답되고, 우두(wudu)를 하고 기도하면 그의 기도가 받아들여진다."),
        "dua_hamm_ibn_masud" to DuaText("슬픔을 위한 두아(Ibn Mas'ud)", "오 알라, 나는 당신의 종, 당신 종의 아들, 당신 여종의 아들입니다. 내 앞머리는 주의 손에 있고, 나를 향한 주의 명령은 그대로 이루어지며, 나에 대한 주의 법령은 의롭습니다. 당신이 당신 자신을 명명하신 것, 당신의 책에 계시하신 것, 당신의 피조물에게 가르치신 것, 보이지 않는 것에 대한 지식 속에 당신과 함께 간직하신 것 등 당신의 모든 이름으로 당신께 간구하오니, 꾸란을 내 마음의 샘이 되게 하시고, 내 가슴의 빛이 되게 하시고, 내 슬픔을 제거하고 내 근심이 사라지게 하소서.", "슬픔과 괴로움 속에서 — 알라께서는 슬픔을 기쁨으로 바꾸십니다.", "알라께서는 그의 걱정과 슬픔을 제거하시고 그 자리에 기쁨을 주시느니라."),
        "dua_difficulty_sahl" to DuaText("뭔가 어려울 때", "오 알라, 당신이 쉽게 하신 것 외에는 쉬운 것이 없고 당신이 원하시면 어려운 것도 쉽게 만드시나이다.", "뭔가 어렵다고 느낄 때.", "시험과 어려운 작업이 쉬워집니다."),
        "dua_musibah" to DuaText("재난 시(Istirja)", "우리는 알라에게 속해 있으며 그분께로 돌아갈 것입니다. 오 알라시여, 나의 고난을 보상하시고 더 나은 것으로 바꿔 주소서.", "손실이나 재난이 발생한 경우.", "알라는 확실히 더 나은 것을 주십니다. Umm Salamah (RA)이 예언자 ﷺ에게 주어졌습니다."),
        "dua_debt" to DuaText("부채 구제를 위해", "오 알라시여, 당신이 불법으로 만드신 것에 대해 당신이 허용하신 것으로 나에게 충분하게 하시고, 당신의 자비로 당신 이외의 모든 것으로부터 나를 독립하게 하소서.", "빚을 갚기 위해 — Ali (RA)이 가르쳤습니다.", "빚이 산과 같을지라도 하나님께서 해결해 주실 것입니다."),
        "dua_anger" to DuaText("화가 났을 때", "나는 저주받은 자 샤이탄에게서 알라께 피난처를 구합니다.", "화가 났을 때.", "선지자 ﷺ은 이렇게 말했습니다. 만일 그가 이렇게 말한다면 그의 분노는 사라질 것입니다."),
        "dua_waswasa" to DuaText("믿음의 와와사(Waswasa)에 대항하여", "나는 알라와 그의 메신저를 믿습니다.", "믿음에 관한 사탄의 속삭임이 올 때.", "속삭임이 오면 이렇게 말하고 거기에서 멈춰라(또한 알라에게 피난처를 구하라)."),
        "dua_travel_full" to DuaText("완전한 여행 지원", "오 알라, 우리는 이 여정에서 정의와 경건, 그리고 당신을 기쁘게 하는 행동을 위해 당신께 간구합니다. 오 알라여, 이 여행을 쉽게 하시고 거리를 단축시키소서. 오 알라, 당신은 여행의 동반자이시며 가족의 수호자이십니다.", "여행을 떠날 때 'Subhanalladhi sakhkhara' 이후.", "완전한 Sunnah 여행 듀아."),
        "dua_return_travel" to DuaText("여행에서 돌아오는 길", "우리는 돌아와서 회개하고 우리 주님을 예배하고 찬양하고 있습니다.", "여행에서 돌아올 때.", "선지자 ﷺ은 여행에서 돌아올 때 이렇게 말했습니다."),
        "dua_farewell_traveller" to DuaText("여행자에게 작별 인사하기", "나는 당신의 종교와 신뢰, 그리고 당신의 행위의 결과를 알라에게 맡깁니다.", "여행자에게 작별 인사를 할 때.", "알라에게 맡겨진 것은 결코 사라지지 않습니다."),
        "dua_entering_town" to DuaText("한 장소에 정차", "나는 알라께서 창조하신 모든 것의 악으로부터 그분의 완전한 말씀으로 피난처를 구합니다.", "어떤 장소에 들를 때나 새로운 도시에 도착할 때.", "그가 그곳을 떠나기까지는 아무 것도 그에게 해를 끼치지 못할 것이다."),
        "dua_boarding_ship" to DuaText("선박/차량 탑승", "알라의 이름으로 항해와 정박이 이루어집니다. 진실로 나의 주님은 용서하시고 자비로우십니다.", "배나 차량에 탑승할 때 — 선지자 누 (AS)의 말씀입니다.", "꾸란 구절 — Nuh의 (AS) 방주의 듀아."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Hayyul-Qayyum과 함께하는 Istighfar", "나는 알라 외에는 신이 없으며 영생하시는 분, 유지하시는 분인 알라에게 용서를 구하고 회개하며 그분께로 향합니다.", "회개를 위해.", "비록 그가 전쟁터에서 도망쳤을지라도 그의 죄는 용서받았습니다."),
        "dua_rabbighfir_warham" to DuaText("래비피어 워햄", "나의 주님, 용서하시고 자비를 베푸소서. 당신은 자비를 베푸는 자들 중에서 가장 뛰어난 분이시기 때문입니다.", "꾸란 두아(A Quranic dua) - 용서와 자비를 위한 것입니다.", "Surah al-Mu'minun의 마지막 구절입니다."),
        "dua_majlis_kaffarah" to DuaText("카파라트 알 마즐리스", "오 알라, 당신께 영광을 돌리고 당신께 찬미를 드립니다. 나는 당신 외에는 신이 없음을 간증드립니다. 나는 당신의 용서를 구하고 회개하며 당신께로 향합니다.", "모임에서 일어날 때.", "그것은 모임에서 어떤 잘못된 말을 했는지에 대한 속죄가 됩니다."),
        "dua_jami_forgiveness" to DuaText("포괄적인 용서", "오 알라, 나의 실수, 나의 무지, 나의 지나친 일, 그리고 당신이 나보다 더 잘 아시는 모든 것을 용서해 주십시오.", "예언자 ﷺ의 포괄적인 이중입니다.", "예언자 ﷺ이 이 듀아를 만들곤 했습니다."),
        "dua_parents_nuh" to DuaText("Dua of Nuh (AS) 부모님을 위한", "나의 주님, 저를 용서해 주십시오. 저희 부모님, 신자로서 제 집에 들어오는 모든 사람, 그리고 모든 신자들을 용서해 주십시오.", "부모님과 신자들에게.", "예언자 누 (AS)의 두아."),
        "dua_shukr_parents" to DuaText("부모와 의로운 자손에 대한 감사", "주여, 저와 제 부모에게 베풀어주신 은혜에 감사하게 하시고, 아버지를 기쁘시게 하는 의로운 일을 행하게 하시고, 제 후손을 의롭게 되게 하소서. 나는 회개하여 당신께로 향하고 복종하는 이들 중에 하나입니다.", "마흔 살이 된 꾸란의 두아.", "감사, 선행, 자녀의 의로움이 모두 하나의 두아입니다."),
        "dua_intimacy" to DuaText("결혼관계 전", "알라의 이름으로. 오 알라, Shaytan을 우리에게서 멀리하고 Shaytan을 당신이 우리에게 허락하는 것(자녀)으로부터 멀리 두십시오.", "결혼 관계 전.", "아이에게 명령이 내려지면 샤이탄은 결코 아이에게 해를 끼치지 않을 것입니다."),
        "dua_ibrahim_children_protection" to DuaText("가정과 어린이 보호", "나의 주여, 이 성을 견고하게 하시고 나와 내 자녀들이 우상을 섬기지 않게 하소서.", "예언자 이브라힘 (AS)의 두아 — 도시와 그의 아이들의 안전을 위해.", "tawhid에 대한 굳건함을 유지하기위한 이중입니다."),
        "dua_drinking_milk" to DuaText("우유를 마실 때", "오 알라, 우리를 위해 그것을 축복하시고 더 많은 것을 우리에게 주소서.", "우유를 마실 때.", "우유는 음식으로도, 음료로도 충분합니다."),
        "dua_iftar_host" to DuaText("다른 사람들과 금식할 때", "금식하는 사람들이 당신과 함께 금식을 하게 하시고, 의인들이 당신의 음식을 먹게 하시고, 천사들이 당신을 위하여 기도하게 하소서.", "누군가의 집에서 금식을 중단할 때.", "호스트에 대한 선지자의 ﷺ dua입니다."),
    )
}
